-- ════════════════════════════════════════════════════════
-- 212 — Lot 4b du second recensement : la scene nicaraguayenne sans usine
-- ────────────────────────────────────────────────────────
-- Six maisons rangees par la fabrique qui les roule :
--   chez ROJAS          Stolen Throne, Ezra Zion
--   chez LUCIANO        Ozgener Family Cigars (Aramas chez La Alianza)
--   chez ROCKY PATEL    All Saints
--   chez LA CORONA      Serino  (fabrique nommee, sans fiche : pas de marque propre)
--   chez AGANORSA       Sindicato
--
-- ORTEGA CIGARS EST REPORTEE. La seule trace recente est un catalogue
-- de detaillant annoncant le retour du Cubao ; ni date, ni confirmation
-- que la maison est active. Une fiche au present sur une maison peut-
-- etre dormante serait la faute de Mombacho a l'envers.
--
-- Deux renvois deviennent reciproques : Nomad appartient a Ezra Zion
-- depuis septembre 2018 (la fiche Nomad le dira au lot 5) ; CAO et
-- Ozgener sont pere et fils.
--
-- Sindicato est une marque de detaillants — et la fiche dit en quoi
-- elle n'est pas Black Swan : une societe avec un catalogue permanent,
-- pas une serie commandee a des fabriques tournantes.
--
-- `producer_countries.brands` lu dans la base et reecrit en litteral.
-- Domaines verifies au DNS avant ecriture : cigarlifeguy.com,
-- smallbatchcigar.com, stolenthronecigars.com, atlanticcigar.com,
-- cigar-coop.com, halfwheel.com, tinderbox.com, blindmanspuff.com,
-- cigaraficionado.com, jrcigars.com, cigars.com, tobaccobusiness.com,
-- allsaintscigars.com, bovedainc.com, cigardojo.com, serinocigars.com,
-- leafenthusiast.com, sindicatocigars.com.
-- ════════════════════════════════════════════════════════

-- ── Stolen Throne ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Stolen Throne',
        'nicaragua',
        '2019 — Virginie ; chez Noel Rojas',
        'Sans usine — Noel Rojas, Tabacalera Flor de San Luis puis Rojas Cigar Factory, Estelí',
        'cigarlifeguy.com « Lee Marsh of Stolen Throne Cigars: Interview » et smallbatchcigar.com (lancée en Virginie en 2019 par Richard « Lee » Marsh, avec Noel Rojas comme maître assembleur, à la Tabacalera Flor de San Luis ; Crook of the Crown et Call to Arms, les deux premières ; Three Kingdoms, Yorktown Fleet) ; stolenthronecigars.com ; atlanticcigar.com (Crook of the Crown 5th Anniversary)',
        'Stolen Throne — le trône volé — est une maison de Virginie qui n''a jamais roulé un cigare elle-même, et qui le dit. Richard « Lee » Marsh l''a lancée en 2019 en s''associant à Noel Rojas, l''assembleur cubain d''Estelí dont l''atlas porte la fiche : les premiers cigares sont sortis de la Tabacalera Flor de San Luis, où Rojas travaillait alors, avant la Rojas Cigar Factory. Ezra Zion, Nomad et Emilio ont fait le même choix ; Rojas roule pour quatre maisons de cet atlas.

Les deux premières lignes ont fait la réputation : Crook of the Crown, l''usurpateur, et Call to Arms, l''appel aux armes. Three Kingdoms et Yorktown Fleet ont suivi — la seconde sur un nom de la guerre d''Indépendance, la Virginie oblige. Le cinquième anniversaire, en 2024, a eu son Corona.

Un nom de marque qui raconte une histoire, un assembleur nommé, une fabrique nommée : c''est ce que l''atlas demande, et la fiche n''a rien à y ajouter.',
        '[{"name":"Crook of the Crown","color":"#7A2E1E","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"L''usurpateur — la première ligne, 2019. Un Corona pour le cinquième anniversaire."},{"name":"Call to Arms","color":"#4A3728","force":"Full","wrapper":"Non divulguée","vitolas":[],"story":"L''appel aux armes — la seconde."},{"name":"Yorktown Fleet","color":"#3E4A6B","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"Un nom de la guerre d''Indépendance, pour une maison de Virginie."}]',
        'Stolen Throne is a Virginia house that has never rolled a cigar itself, and says so. Richard "Lee" Marsh launched it in 2019 by partnering with Noel Rojas, the Cuban blender in Estelí whose entry this atlas carries: the first cigars came out of Tabacalera Flor de San Luis, where Rojas was then working, before the Rojas Cigar Factory. Ezra Zion, Nomad and Emilio made the same choice; Rojas rolls for four houses in this atlas.

The first two lines built the reputation: Crook of the Crown, the usurper, and Call to Arms. Three Kingdoms and Yorktown Fleet followed — the latter on a name from the War of Independence, Virginia obliging. The fifth anniversary, in 2024, had its Corona.

A brand name that tells a story, a named blender, a named factory: that is what this atlas asks, and the entry has nothing to add.',
        '[{"name":"Crook of the Crown","color":"#7A2E1E","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"The usurper — the first line, 2019. A Corona for the fifth anniversary."},{"name":"Call to Arms","color":"#4A3728","force":"Full","wrapper":"Undisclosed","vitolas":[],"story":"The call to arms — the second."},{"name":"Yorktown Fleet","color":"#3E4A6B","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"A name from the War of Independence, for a Virginia house."}]',
        'Stolen Throne — el trono robado — es una casa de Virginia que nunca lió un puro por sí misma, y lo dice. Richard «Lee» Marsh la lanzó en 2019 asociándose con Noel Rojas, el ligador cubano de Estelí cuya ficha lleva este atlas: los primeros puros salieron de la Tabacalera Flor de San Luis, donde Rojas trabajaba entonces, antes de la Rojas Cigar Factory. Ezra Zion, Nomad y Emilio hicieron la misma elección; Rojas lía para cuatro casas de este atlas.

Las dos primeras líneas hicieron la reputación: Crook of the Crown, el usurpador, y Call to Arms, la llamada a las armas. Three Kingdoms y Yorktown Fleet siguieron — la segunda con un nombre de la guerra de Independencia, Virginia obliga. El quinto aniversario, en 2024, tuvo su Corona.

Un nombre de marca que cuenta una historia, un ligador nombrado, una fábrica nombrada: es lo que este atlas pide, y la ficha no tiene nada que añadir.',
        '[{"name":"Crook of the Crown","color":"#7A2E1E","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"El usurpador — la primera línea, 2019. Un Corona para el quinto aniversario."},{"name":"Call to Arms","color":"#4A3728","force":"Full","wrapper":"No divulgada","vitolas":[],"story":"La llamada a las armas — la segunda."},{"name":"Yorktown Fleet","color":"#3E4A6B","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"Un nombre de la guerra de Independencia, para una casa de Virginia."}]',
        'Stolen Throne — der gestohlene Thron — ist ein Haus aus Virginia, das nie selbst eine Zigarre gerollt hat, und das sagt es. Richard „Lee" Marsh lancierte es 2019 in Partnerschaft mit Noel Rojas, dem kubanischen Blender in Estelí, dessen Eintrag dieser Atlas führt: Die ersten Zigarren kamen aus der Tabacalera Flor de San Luis, wo Rojas damals arbeitete, vor der Rojas Cigar Factory. Ezra Zion, Nomad und Emilio trafen dieselbe Wahl; Rojas rollt für vier Häuser dieses Atlas.

Die ersten beiden Linien machten den Ruf: Crook of the Crown, der Usurpator, und Call to Arms, der Ruf zu den Waffen. Three Kingdoms und Yorktown Fleet folgten — Letztere mit einem Namen aus dem Unabhängigkeitskrieg, Virginia verpflichtet. Das fünfte Jubiläum 2024 bekam seine Corona.

Ein Markenname, der eine Geschichte erzählt, ein benannter Blender, eine benannte Fabrik: Das verlangt dieser Atlas, und der Eintrag hat nichts hinzuzufügen.',
        '[{"name":"Crook of the Crown","color":"#7A2E1E","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Der Usurpator — die erste Linie, 2019. Eine Corona zum fünften Jubiläum."},{"name":"Call to Arms","color":"#4A3728","force":"Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Der Ruf zu den Waffen — die zweite."},{"name":"Yorktown Fleet","color":"#3E4A6B","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Ein Name aus dem Unabhängigkeitskrieg, für ein Haus aus Virginia."}]',
        'Stolen Throne——被窃的王座——是弗吉尼亚的一家公司，从未自己卷过一支雪茄，并且直言不讳。理查德·「李」·马什2019年与埃斯特利的古巴调配师诺埃尔·罗哈斯合作创立——本图集载有罗哈斯词条：首批雪茄出自罗哈斯当时任职的 Tabacalera Flor de San Luis，早于 Rojas Cigar Factory。Ezra Zion、Nomad 与 Emilio 做了同样的选择；罗哈斯为本图集的四家公司卷制。

前两条线奠定了名声：Crook of the Crown——篡位者，与 Call to Arms——号召武装。随后是 Three Kingdoms 与 Yorktown Fleet——后者取自独立战争的地名，弗吉尼亚使然。2024年的五周年有自己的 Corona。

讲故事的品牌名、点名的调配师、点名的工厂：这正是本图集所要求的，词条无须添加什么。',
        '[{"name":"Crook of the Crown","color":"#7A2E1E","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"篡位者——第一条线，2019年。五周年出了一支 Corona。"},{"name":"Call to Arms","color":"#4A3728","force":"Full","wrapper":"未公开","vitolas":[],"story":"号召武装——第二条线。"},{"name":"Yorktown Fleet","color":"#3E4A6B","force":"Medium","wrapper":"未公开","vitolas":[],"story":"独立战争的地名，给一家弗吉尼亚的公司。"}]',
        'ستولن ثرون — العرش المسروق — دارٌ من فرجينيا لم تلفّ سيجارًا بنفسها قطّ، وتقول ذلك. أطلقها ريتشارد «لي» مارش سنة 2019 بالشراكة مع نويل روخاس، المزّاج الكوبي في إستيلي الذي يحمل هذا الأطلس بطاقته: خرجت السيجارات الأولى من Tabacalera Flor de San Luis، حيث كان روخاس يعمل آنذاك، قبل Rojas Cigar Factory. واختارت Ezra Zion وNomad وEmilio الاختيار نفسه؛ فروخاس يلفّ لأربع دور في هذا الأطلس.

صنع الخطّان الأوّلان السمعة: Crook of the Crown، المغتصب، وCall to Arms، النداء إلى السلاح. وتبعهما Three Kingdoms وYorktown Fleet — الثاني باسم من حرب الاستقلال، وفرجينيا تُلزم. وكان للذكرى الخامسة سنة 2024 سيجارها Corona.

اسمُ علامة يروي قصّة، ومزّاجٌ مسمّى، ومصنعٌ مسمّى: ذلك ما يطلبه هذا الأطلس، وليس للبطاقة ما تضيفه.',
        '[{"name":"Crook of the Crown","color":"#7A2E1E","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"المغتصب — الخطّ الأوّل، 2019. سيجار Corona للذكرى الخامسة."},{"name":"Call to Arms","color":"#4A3728","force":"Full","wrapper":"غير معلن","vitolas":[],"story":"النداء إلى السلاح — الثاني."},{"name":"Yorktown Fleet","color":"#3E4A6B","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"اسم من حرب الاستقلال، لدار من فرجينيا."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Ezra Zion ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Ezra Zion',
        'nicaragua',
        'Juillet 2012 — Texas ; chez Noel Rojas',
        'Sans usine — Noel Rojas (Aromas de Jalapa, puis ses ateliers suivants), Estelí',
        'cigar-coop.com « Ezra Zion All My EX''s » et « Fred Rewey Sells Nomad Cigar Company to Ezra Zion » (septembre 2018) ; halfwheel.com « Ezra Zion Honor Series FHK Truth » (débuts en juillet 2012 avec l''Honor Series Reagan et Inception, devenue Jamais Vu ; Tantrum ; les trois premiers assemblages sont des puros nicaraguayens ; collaboration avec la fabrique Aromas de Jalapa de Noel Rojas) ; tinderbox.com (fondée au Texas par Chris Kelly et Kyle Hoover) ; blindmanspuff.com (rachat de Cigar Federation)',
        'Ezra Zion est une maison texane fondée par deux amateurs, Chris Kelly et Kyle Hoover, qui ont débuté en juillet 2012 avec deux lignes — l''Honor Series Reagan et une Inception rebaptisée depuis Jamais Vu — puis Tantrum. Les trois premiers assemblages étaient des puros nicaraguayens, et c''est un Nicaraguayen d''adoption qui les a faits : Noel Rojas, l''assembleur cubain d''Estelí dont l''atlas porte la fiche, alors dans son atelier Aromas de Jalapa. L''atlas la classe donc au Nicaragua, où ses cigares sont roulés, pas au Texas, où ils sont pensés.

La maison vend en petites séries, avec des noms qui sont des phrases — All My EX''s, FHK Truth — et une manière de raconter chaque cigare comme une histoire. C''est un modèle d''édition plus que de manufacture, et il a trouvé son public.

En septembre 2018, Fred Rewey lui a vendu Nomad Cigar Company, dont l''atlas porte la fiche : Ezra Zion possède donc deux marques de cet atlas, et Nomad, elle aussi, passe par les mains de Rojas. Elle a aussi racheté Cigar Federation, un forum d''amateurs — une maison qui possède le lieu où l''on parle d''elle.',
        '[{"name":"Jamais Vu","color":"#5B3A29","force":"Medium-Full","wrapper":"Puro nicaraguayen","vitolas":[],"story":"Née Inception en juillet 2012, rebaptisée. L''un des trois premiers puros."},{"name":"Honor Series","color":"#4A3728","force":"Full","wrapper":"Non divulguée","vitolas":[],"story":"Des cigares qui honorent des personnes — Reagan le premier, FHK ensuite."},{"name":"Tantrum","color":"#7A2E1E","force":"Full","wrapper":"Non divulguée","vitolas":[],"story":"Le troisième des puros de départ."}]',
        'Ezra Zion is a Texas house founded by two enthusiasts, Chris Kelly and Kyle Hoover, who began in July 2012 with two lines — the Honor Series Reagan and an Inception since renamed Jamais Vu — then Tantrum. The first three blends were Nicaraguan puros, and it was a Nicaraguan by adoption who made them: Noel Rojas, the Cuban blender in Estelí whose entry this atlas carries, then in his Aromas de Jalapa workshop. This atlas therefore classifies it in Nicaragua, where its cigars are rolled, not in Texas, where they are conceived.

The house sells in small series, with names that are sentences — All My EX''s, FHK Truth — and a way of telling each cigar as a story. It is a publishing model more than a manufacturing one, and it found its public.

In September 2018, Fred Rewey sold it Nomad Cigar Company, whose entry this atlas carries: Ezra Zion thus owns two brands of this atlas, and Nomad, too, passes through Rojas''s hands. It also bought Cigar Federation, an enthusiasts'' forum — a house that owns the place where people talk about it.',
        '[{"name":"Jamais Vu","color":"#5B3A29","force":"Medium-Full","wrapper":"Nicaraguan puro","vitolas":[],"story":"Born Inception in July 2012, renamed. One of the first three puros."},{"name":"Honor Series","color":"#4A3728","force":"Full","wrapper":"Undisclosed","vitolas":[],"story":"Cigars that honour people — Reagan first, FHK next."},{"name":"Tantrum","color":"#7A2E1E","force":"Full","wrapper":"Undisclosed","vitolas":[],"story":"The third of the founding puros."}]',
        'Ezra Zion es una casa texana fundada por dos aficionados, Chris Kelly y Kyle Hoover, que empezaron en julio de 2012 con dos líneas — la Honor Series Reagan y una Inception desde entonces rebautizada Jamais Vu — y luego Tantrum. Las tres primeras ligadas eran puros nicaragüenses, y fue un nicaragüense de adopción quien las hizo: Noel Rojas, el ligador cubano de Estelí cuya ficha lleva este atlas, entonces en su taller Aromas de Jalapa. Este atlas la clasifica pues en Nicaragua, donde se lían sus puros, no en Texas, donde se piensan.

La casa vende en pequeñas series, con nombres que son frases — All My EX''s, FHK Truth — y una manera de contar cada puro como una historia. Es un modelo de edición más que de manufactura, y encontró su público.

En septiembre de 2018, Fred Rewey le vendió Nomad Cigar Company, cuya ficha lleva este atlas: Ezra Zion posee pues dos marcas de este atlas, y Nomad también pasa por las manos de Rojas. Compró además Cigar Federation, un foro de aficionados — una casa que posee el lugar donde se habla de ella.',
        '[{"name":"Jamais Vu","color":"#5B3A29","force":"Medium-Full","wrapper":"Puro nicaragüense","vitolas":[],"story":"Nacida Inception en julio de 2012, rebautizada. Uno de los tres primeros puros."},{"name":"Honor Series","color":"#4A3728","force":"Full","wrapper":"No divulgada","vitolas":[],"story":"Puros que honran a personas — Reagan primero, FHK después."},{"name":"Tantrum","color":"#7A2E1E","force":"Full","wrapper":"No divulgada","vitolas":[],"story":"El tercero de los puros iniciales."}]',
        'Ezra Zion ist ein texanisches Haus, gegründet von zwei Liebhabern, Chris Kelly und Kyle Hoover, die im Juli 2012 mit zwei Linien begannen — der Honor Series Reagan und einer seither in Jamais Vu umbenannten Inception — dann Tantrum. Die ersten drei Blends waren nicaraguanische Puros, und ein Nicaraguaner durch Adoption machte sie: Noel Rojas, der kubanische Blender in Estelí, dessen Eintrag dieser Atlas führt, damals in seiner Werkstatt Aromas de Jalapa. Dieser Atlas ordnet sie daher in Nicaragua ein, wo ihre Zigarren gerollt werden, nicht in Texas, wo sie erdacht werden.

Das Haus verkauft in kleinen Serien, mit Namen, die Sätze sind — All My EX''s, FHK Truth — und einer Art, jede Zigarre als Geschichte zu erzählen. Es ist eher ein Verlags- als ein Fertigungsmodell, und es fand sein Publikum.

Im September 2018 verkaufte ihm Fred Rewey die Nomad Cigar Company, deren Eintrag dieser Atlas führt: Ezra Zion besitzt damit zwei Marken dieses Atlas, und auch Nomad geht durch Rojas'' Hände. Es kaufte außerdem Cigar Federation, ein Liebhaberforum — ein Haus, dem der Ort gehört, an dem man über es spricht.',
        '[{"name":"Jamais Vu","color":"#5B3A29","force":"Medium-Full","wrapper":"Nicaraguanischer Puro","vitolas":[],"story":"Geboren als Inception im Juli 2012, umbenannt. Einer der ersten drei Puros."},{"name":"Honor Series","color":"#4A3728","force":"Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Zigarren, die Menschen ehren — Reagan zuerst, dann FHK."},{"name":"Tantrum","color":"#7A2E1E","force":"Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Der dritte der Gründungs-Puros."}]',
        'Ezra Zion 是一家得克萨斯公司，由两位爱好者克里斯·凯利与凯尔·胡佛创办，2012年7月以两条线起步——Honor Series Reagan 与后来更名为 Jamais Vu 的 Inception——继而 Tantrum。前三款配方均为尼加拉瓜纯料，制作者是一位「归化」的尼加拉瓜人：埃斯特利的古巴调配师诺埃尔·罗哈斯——本图集载有其词条——当时在他的 Aromas de Jalapa 作坊。本图集因此把它归入雪茄卷制之地尼加拉瓜，而非构思之地得克萨斯。

公司以小批量销售，名字都是句子——All My EX''s、FHK Truth——每支雪茄都当作一个故事来讲。这更像出版而非制造的模式，且找到了自己的受众。

2018年9月，弗雷德·雷维把 Nomad Cigar Company 卖给了它——本图集载有 Nomad 词条：Ezra Zion 因此拥有本图集的两个品牌，而 Nomad 同样经罗哈斯之手。它还收购了爱好者论坛 Cigar Federation——一家拥有人们谈论它的场所的公司。',
        '[{"name":"Jamais Vu","color":"#5B3A29","force":"Medium-Full","wrapper":"尼加拉瓜纯料","vitolas":[],"story":"2012年7月以 Inception 之名诞生，后更名。最初三款纯料之一。"},{"name":"Honor Series","color":"#4A3728","force":"Full","wrapper":"未公开","vitolas":[],"story":"致敬人物的雪茄——先是里根，后是 FHK。"},{"name":"Tantrum","color":"#7A2E1E","force":"Full","wrapper":"未公开","vitolas":[],"story":"最初三款纯料中的第三款。"}]',
        'إزرا زايون دارٌ تكساسية أسّسها هاويان، كريس كيلي وكايل هوفر، بدآ في تموز/يوليو 2012 بخطّين — Honor Series Reagan وInception التي أُعيدت تسميتها منذ ذلك الحين Jamais Vu — ثم Tantrum. كانت المزجات الثلاث الأولى سيجارات نيكاراغوية خالصة، وصنعها نيكاراغوي بالتبنّي: نويل روخاس، المزّاج الكوبي في إستيلي الذي يحمل هذا الأطلس بطاقته، وكان آنذاك في ورشته Aromas de Jalapa. لذلك يصنّفها هذا الأطلس في نيكاراغوا حيث تُلفّ سيجاراتها، لا في تكساس حيث تُتصوَّر.

تبيع الدار بسلاسل صغيرة، بأسماء هي جُمل — All My EX''s وFHK Truth — وبطريقةٍ تروي كلّ سيجار قصّةً. إنّه نموذج نشرٍ أكثر منه نموذج صنع، وقد وجد جمهوره.

وفي أيلول/سبتمبر 2018 باعها فريد ريوي شركة Nomad Cigar Company التي يحمل هذا الأطلس بطاقتها: فإزرا زايون تملك إذن علامتين من هذا الأطلس، وNomad أيضًا تمرّ بيدي روخاس. واشترت كذلك Cigar Federation، منتدى هواة — دارٌ تملك المكان الذي يُتحدَّث فيه عنها.',
        '[{"name":"Jamais Vu","color":"#5B3A29","force":"Medium-Full","wrapper":"نيكاراغوي خالص","vitolas":[],"story":"وُلدت باسم Inception في تموز/يوليو 2012 ثم أُعيدت تسميتها. أحد الثلاثة الأوائل الخالصة."},{"name":"Honor Series","color":"#4A3728","force":"Full","wrapper":"غير معلن","vitolas":[],"story":"سيجارات تكرّم أشخاصًا — ريغان أوّلًا، ثم FHK."},{"name":"Tantrum","color":"#7A2E1E","force":"Full","wrapper":"غير معلن","vitolas":[],"story":"الثالث بين السيجارات الخالصة الأولى."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Ozgener Family Cigars ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Ozgener Family Cigars',
        'nicaragua',
        '2022 — Tim Ozgener ; chez Luciano',
        'Sans usine — Luciano Cigar Factory (ex-Tabacalera Pichardo), Estelí ; Aramas chez La Alianza (E.P. Carrillo), Rép. dominicaine',
        'cigaraficionado.com « Tim Ozgener Returns to Cigar Business » et « Ozgener Family''s Pi Synesthesia » (Tim Ozgener, ancien président de CAO, la maison fondée par son père Cano ; retour début 2022 avec Bosphorus et Pi Synesthesia) ; halfwheel.com « Aramas A55 » (Aramas, mars 2024, du nom du mont Ararat, roulée à La Alianza) ; jrcigars.com et cigars.com (roulée à Tabacalera Pichardo)',
        'Ozgener est un nom que l''atlas connaissait déjà par une autre fiche : CAO, la maison de Nashville fondée par Cano Ozgener, un ingénieur turc devenu cigarier. Tim, son fils, en a été le président avant la vente à General Cigar. Il est revenu au métier au début de 2022, sous son propre nom, avec deux assemblages — Bosphorus, le détroit d''Istanbul, et Pi Synesthesia, un cigare qui joue sur la couleur et la perception.

Elle n''a pas d''usine. Bosphorus et Pi sont roulés chez Luciano, à Estelí — la fabrique d''Eradio Pichardo dont l''atlas porte la fiche ; Aramas, la ligne régulière de mars 2024, nommée d''après le mont Ararat, l''est à La Alianza, la fabrique d''E.P. Carrillo en République dominicaine. La fiche est classée là où sort la majorité, au Nicaragua, et nomme les deux.

C''est un réseau de personnes comme l''atlas en a rencontré chez les Seijas et les Eiroa : un père fonde CAO, un fils la dirige, la vend, puis revient avec les noms de sa famille — le Bosphore, l''Ararat — sur des cigares faits par d''autres.',
        '[{"name":"Bosphorus","color":"#3E4A6B","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Le détroit d''Istanbul — la première ligne, 2022, roulée chez Luciano."},{"name":"Pi Synesthesia","color":"#8B1A6B","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"La couleur et la perception, en édition limitée."},{"name":"Aramas","color":"#6B4226","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Le mont Ararat. La ligne régulière de mars 2024, roulée à La Alianza, chez E.P. Carrillo."}]',
        'Ozgener is a name this atlas already knew through another entry: CAO, the Nashville house founded by Cano Ozgener, a Turkish engineer turned cigar maker. Tim, his son, was its president before the sale to General Cigar. He returned to the trade in early 2022, under his own name, with two blends — Bosphorus, the Istanbul strait, and Pi Synesthesia, a cigar that plays on colour and perception.

It has no factory. Bosphorus and Pi are rolled at Luciano, in Estelí — Eradio Pichardo''s factory, whose entry this atlas carries; Aramas, the regular line of March 2024, named after Mount Ararat, is rolled at La Alianza, E.P. Carrillo''s factory in the Dominican Republic. The entry is classified where the majority comes out, in Nicaragua, and names both.

It is a network of people such as this atlas has met among the Seijas and the Eiroas: a father founds CAO, a son runs it, sells it, then comes back with his family''s names — the Bosphorus, Ararat — on cigars made by others.',
        '[{"name":"Bosphorus","color":"#3E4A6B","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"The Istanbul strait — the first line, 2022, rolled at Luciano."},{"name":"Pi Synesthesia","color":"#8B1A6B","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"Colour and perception, in limited edition."},{"name":"Aramas","color":"#6B4226","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"Mount Ararat. The regular line of March 2024, rolled at La Alianza, at E.P. Carrillo."}]',
        'Ozgener es un nombre que este atlas ya conocía por otra ficha: CAO, la casa de Nashville fundada por Cano Ozgener, un ingeniero turco hecho tabaquero. Tim, su hijo, fue su presidente antes de la venta a General Cigar. Volvió al oficio a principios de 2022, bajo su propio nombre, con dos ligadas — Bosphorus, el estrecho de Estambul, y Pi Synesthesia, un puro que juega con el color y la percepción.

No tiene fábrica. Bosphorus y Pi se lían en Luciano, en Estelí — la fábrica de Eradio Pichardo cuya ficha lleva este atlas; Aramas, la línea regular de marzo de 2024, nombrada por el monte Ararat, se lía en La Alianza, la fábrica de E.P. Carrillo en la República Dominicana. La ficha se clasifica donde sale la mayoría, en Nicaragua, y nombra a ambas.

Es una red de personas como las que este atlas encontró entre los Seijas y los Eiroa: un padre funda CAO, un hijo la dirige, la vende, y luego vuelve con los nombres de su familia — el Bósforo, el Ararat — en puros hechos por otros.',
        '[{"name":"Bosphorus","color":"#3E4A6B","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"El estrecho de Estambul — la primera línea, 2022, liada en Luciano."},{"name":"Pi Synesthesia","color":"#8B1A6B","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"El color y la percepción, en edición limitada."},{"name":"Aramas","color":"#6B4226","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"El monte Ararat. La línea regular de marzo de 2024, liada en La Alianza, en E.P. Carrillo."}]',
        'Ozgener ist ein Name, den dieser Atlas schon aus einem anderen Eintrag kannte: CAO, das Haus aus Nashville, gegründet von Cano Ozgener, einem türkischen Ingenieur, der Zigarrenmacher wurde. Tim, sein Sohn, war dessen Präsident vor dem Verkauf an General Cigar. Anfang 2022 kehrte er unter eigenem Namen ins Metier zurück, mit zwei Blends — Bosphorus, die Meerenge von Istanbul, und Pi Synesthesia, eine Zigarre, die mit Farbe und Wahrnehmung spielt.

Es hat keine Fabrik. Bosphorus und Pi werden bei Luciano in Estelí gerollt — der Fabrik von Eradio Pichardo, deren Eintrag dieser Atlas führt; Aramas, die reguläre Linie vom März 2024, nach dem Berg Ararat benannt, bei La Alianza, der Fabrik von E.P. Carrillo in der Dominikanischen Republik. Der Eintrag ist dort eingeordnet, wo die Mehrheit herauskommt, in Nicaragua, und nennt beide.

Es ist ein Netz von Personen, wie dieser Atlas es bei den Seijas und den Eiroas traf: Ein Vater gründet CAO, ein Sohn führt es, verkauft es und kehrt dann mit den Namen seiner Familie zurück — Bosporus, Ararat — auf Zigarren, die andere machen.',
        '[{"name":"Bosphorus","color":"#3E4A6B","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Die Meerenge von Istanbul — die erste Linie, 2022, bei Luciano gerollt."},{"name":"Pi Synesthesia","color":"#8B1A6B","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Farbe und Wahrnehmung, in limitierter Auflage."},{"name":"Aramas","color":"#6B4226","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Der Berg Ararat. Die reguläre Linie vom März 2024, bei La Alianza, E.P. Carrillo, gerollt."}]',
        '奥兹格纳这个姓，本图集已从另一个词条认识：CAO，纳什维尔那家由土耳其工程师出身的雪茄匠卡诺·奥兹格纳创办的公司。其子蒂姆在出售给 General Cigar 之前任总裁。2022年初他以自己的名字重返行业，带来两款配方——Bosphorus，伊斯坦布尔海峡；Pi Synesthesia，一支玩转色彩与感知的雪茄。

它没有工厂。Bosphorus 与 Pi 在埃斯特利的 Luciano 卷制——埃拉迪奥·皮查尔多的工厂，本图集载有其词条；2024年3月的常规系列 Aramas，以阿拉拉特山命名，在多米尼加共和国 E.P. Carrillo 的 La Alianza 工厂卷制。词条按多数产量所在地归入尼加拉瓜，并点出两厂。

这是本图集在塞哈斯家与埃罗亚家见过的那种人脉网：父亲创办 CAO，儿子执掌、出售，再带着家族的名字——博斯普鲁斯、阿拉拉特——回到由他人制作的雪茄上。',
        '[{"name":"Bosphorus","color":"#3E4A6B","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"伊斯坦布尔海峡——第一条线，2022年，在 Luciano 卷制。"},{"name":"Pi Synesthesia","color":"#8B1A6B","force":"Medium","wrapper":"未公开","vitolas":[],"story":"色彩与感知，限量版。"},{"name":"Aramas","color":"#6B4226","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"阿拉拉特山。2024年3月的常规系列，在 E.P. Carrillo 的 La Alianza 卷制。"}]',
        'أوزغنر اسمٌ عرفه هذا الأطلس من قبل عبر بطاقة أخرى: CAO، دار ناشفيل التي أسّسها كانو أوزغنر، مهندس تركي صار صانع سيجار. وكان تيم، ابنه، رئيسها قبل بيعها لجنرال سيغار. عاد إلى المهنة في مطلع 2022 باسمه، بمزجتين — Bosphorus، مضيق إسطنبول، وPi Synesthesia، سيجار يلعب على اللون والإدراك.

ليس لها مصنع. يُلفّ Bosphorus وPi لدى Luciano في إستيلي — مصنع إراديو بيتشاردو الذي يحمل هذا الأطلس بطاقته؛ أمّا Aramas، الخطّ المنتظم من آذار/مارس 2024، المسمّى على جبل أرارات، فيُلفّ في La Alianza، مصنع E.P. Carrillo في جمهورية الدومينيكان. تُصنَّف البطاقة حيث تخرج الأغلبية، في نيكاراغوا، وتسمّي الاثنين.

إنّها شبكة أشخاص كما التقاها هذا الأطلس عند آل سيخاس وآل إيروا: أبٌ يؤسّس CAO، وابنٌ يديرها ويبيعها، ثم يعود بأسماء عائلته — البوسفور وأرارات — على سيجارات يصنعها غيره.',
        '[{"name":"Bosphorus","color":"#3E4A6B","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"مضيق إسطنبول — الخطّ الأوّل، 2022، يُلفّ لدى Luciano."},{"name":"Pi Synesthesia","color":"#8B1A6B","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"اللون والإدراك، بإصدار محدود."},{"name":"Aramas","color":"#6B4226","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"جبل أرارات. الخطّ المنتظم من آذار/مارس 2024، يُلفّ في La Alianza لدى E.P. Carrillo."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── All Saints Cigars ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('All Saints Cigars',
        'nicaragua',
        '2018 — Micky Pegg ; chez Rocky Patel (TAVICUSA)',
        'Sans usine — TAVICUSA, la fabrique de Rocky Patel à Estelí',
        'tobaccobusiness.com « Going All In: All Saints Cigars » et cigar-coop.com « PCA 2021 Report: All Saints Cigars » (fondée en 2018 par Micky Pegg avec Frank Layo et Martin Corboy ; chaque cigare roulé à la TAVICUSA de Rocky Patel, née d''une longue relation entre Pegg et Patel ; Solamente, édition limitée en un seul format 5×58, le premier succès ; Dedicación, première production régulière ; Saint Francis, d''après François d''Assise, en 2021) ; allsaintscigars.com ; bovedainc.com (entretien avec Micky Pegg)',
        'All Saints est une maison de 2018, fondée par Micky Pegg avec deux amis, Frank Layo et Martin Corboy. Elle n''a pas d''usine : chaque cigare est roulé à la TAVICUSA, la fabrique de Rocky Patel à Estelí, dont l''atlas porte la fiche — le fruit, dit Pegg, d''une longue relation avec Patel. Le classement au Nicaragua suit l''atelier.

Le nom promet des saints, et le catalogue a mis un moment à en livrer un. Solamente, le premier succès, était une édition limitée en un seul format, 5 × 58 — un seul cigare, comme le nom le dit. Dedicación a suivi, première ligne de production régulière, que Pegg présente comme un hommage à ceux envers qui il se sent redevable. Puis, en 2021, Saint Francis — François d''Assise — a été le premier cigare de la maison à porter vraiment le nom d''un saint.

Trois lignes, une fabrique, un fondateur qui raconte : c''est une maison de la scène boutique telle que l''atlas en a désormais beaucoup, et sa fiche tient dans ce qu''elle nomme.',
        '[{"name":"Solamente","color":"#4A3728","force":"Full","wrapper":"Non divulguée","vitolas":[],"story":"Le premier succès — une édition limitée en un seul format, 5 × 58."},{"name":"Dedicación","color":"#6B4226","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"La première ligne régulière — un hommage, dit le fondateur."},{"name":"Saint Francis","color":"#8B5A2B","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"François d''Assise — en 2021, le premier saint du catalogue."}]',
        'All Saints is a house of 2018, founded by Micky Pegg with two friends, Frank Layo and Martin Corboy. It has no factory: every cigar is rolled at TAVICUSA, Rocky Patel''s factory in Estelí, whose entry this atlas carries — the fruit, Pegg says, of a long relationship with Patel. The Nicaraguan classification follows the workshop.

The name promises saints, and the catalogue took a while to deliver one. Solamente, the first hit, was a limited edition in a single size, 5 × 58 — one cigar only, as the name says. Dedicación followed, the first regular-production line, which Pegg presents as a tribute to those he feels indebted to. Then, in 2021, Saint Francis — Francis of Assisi — was the house''s first cigar to truly carry a saint''s name.

Three lines, one factory, a founder who tells the story: it is a boutique-scene house such as this atlas now has many of, and its entry holds in what it names.',
        '[{"name":"Solamente","color":"#4A3728","force":"Full","wrapper":"Undisclosed","vitolas":[],"story":"The first hit — a limited edition in a single size, 5 × 58."},{"name":"Dedicación","color":"#6B4226","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"The first regular line — a tribute, the founder says."},{"name":"Saint Francis","color":"#8B5A2B","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"Francis of Assisi — in 2021, the first saint in the catalogue."}]',
        'All Saints es una casa de 2018, fundada por Micky Pegg con dos amigos, Frank Layo y Martin Corboy. No tiene fábrica: cada puro se lía en TAVICUSA, la fábrica de Rocky Patel en Estelí, cuya ficha lleva este atlas — el fruto, dice Pegg, de una larga relación con Patel. La clasificación en Nicaragua sigue al taller.

El nombre promete santos, y el catálogo tardó en entregar uno. Solamente, el primer éxito, era una edición limitada en un solo formato, 5 × 58 — un solo puro, como dice el nombre. Dedicación siguió, primera línea de producción regular, que Pegg presenta como un homenaje a quienes se siente deudor. Luego, en 2021, Saint Francis — Francisco de Asís — fue el primer puro de la casa en llevar de veras el nombre de un santo.

Tres líneas, una fábrica, un fundador que cuenta: es una casa de la escena boutique como este atlas ya tiene muchas, y su ficha cabe en lo que nombra.',
        '[{"name":"Solamente","color":"#4A3728","force":"Full","wrapper":"No divulgada","vitolas":[],"story":"El primer éxito — una edición limitada en un solo formato, 5 × 58."},{"name":"Dedicación","color":"#6B4226","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"La primera línea regular — un homenaje, dice el fundador."},{"name":"Saint Francis","color":"#8B5A2B","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"Francisco de Asís — en 2021, el primer santo del catálogo."}]',
        'All Saints ist ein Haus von 2018, gegründet von Micky Pegg mit zwei Freunden, Frank Layo und Martin Corboy. Es hat keine Fabrik: Jede Zigarre wird bei TAVICUSA gerollt, der Fabrik von Rocky Patel in Estelí, deren Eintrag dieser Atlas führt — die Frucht, sagt Pegg, einer langen Beziehung zu Patel. Die Einordnung in Nicaragua folgt der Werkstatt.

Der Name verspricht Heilige, und der Katalog brauchte eine Weile, um einen zu liefern. Solamente, der erste Erfolg, war eine limitierte Auflage in einem einzigen Format, 5 × 58 — nur eine Zigarre, wie der Name sagt. Dedicación folgte, die erste reguläre Linie, die Pegg als Hommage an jene vorstellt, denen er sich verpflichtet fühlt. Dann, 2021, war Saint Francis — Franz von Assisi — die erste Zigarre des Hauses, die wirklich den Namen eines Heiligen trug.

Drei Linien, eine Fabrik, ein Gründer, der erzählt: Es ist ein Haus der Boutique-Szene, wie dieser Atlas inzwischen viele hat, und sein Eintrag hält sich an das, was es benennt.',
        '[{"name":"Solamente","color":"#4A3728","force":"Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Der erste Erfolg — eine limitierte Auflage in einem einzigen Format, 5 × 58."},{"name":"Dedicación","color":"#6B4226","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Die erste reguläre Linie — eine Hommage, sagt der Gründer."},{"name":"Saint Francis","color":"#8B5A2B","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Franz von Assisi — 2021 der erste Heilige im Katalog."}]',
        'All Saints 是2018年的公司，由米基·佩格与两位朋友弗兰克·拉约、马丁·科尔博伊创办。它没有工厂：每支雪茄都在埃斯特利洛基·帕特尔的 TAVICUSA 厂卷制——本图集载有其词条——佩格说，这是他与帕特尔长期交情的结果。归入尼加拉瓜依据的是作坊。

名字许诺了众圣徒，目录却过了一阵才交出一位。首个成功之作 Solamente 是单一尺寸 5×58 的限量版——正如其名，只此一支。随后是 Dedicación，第一条常规生产线，佩格称之为向所有他心怀感激之人的致敬。然后是2021年的 Saint Francis——阿西西的方济各——这家公司第一支真正冠以圣徒之名的雪茄。

三条线、一家工厂、一位讲故事的创始人：这是本图集如今已收录许多的精品雪茄公司，词条止于它所点名的东西。',
        '[{"name":"Solamente","color":"#4A3728","force":"Full","wrapper":"未公开","vitolas":[],"story":"首个成功之作——单一尺寸 5×58 的限量版。"},{"name":"Dedicación","color":"#6B4226","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"第一条常规线——创始人说是一份致敬。"},{"name":"Saint Francis","color":"#8B5A2B","force":"Medium","wrapper":"未公开","vitolas":[],"story":"阿西西的方济各——2021年，目录里的第一位圣徒。"}]',
        'أول سينتس دارٌ من 2018، أسّسها ميكي بيغ مع صديقين، فرانك لايو ومارتن كوربوي. ليس لها مصنع: كلّ سيجار يُلفّ في TAVICUSA، مصنع روكي باتيل في إستيلي الذي يحمل هذا الأطلس بطاقته — ثمرةُ علاقة طويلة مع باتيل، كما يقول بيغ. والتصنيف في نيكاراغوا يتبع الورشة.

يعد الاسم بقدّيسين، واستغرق الكتالوج وقتًا ليقدّم واحدًا. كان Solamente، النجاح الأوّل، إصدارًا محدودًا بقياس واحد، 5 × 58 — سيجار واحد فقط، كما يقول الاسم. وتبعه Dedicación، أوّل خطّ إنتاج منتظم، ويقدّمه بيغ تحيّةً لمن يشعر بالامتنان لهم. ثم، في 2021، كان Saint Francis — فرنسيس الأسيزي — أوّل سيجار للدار يحمل اسم قدّيس حقًّا.

ثلاثة خطوط، ومصنع واحد، ومؤسّس يروي: إنّها دار من مشهد البوتيك كما صار لهذا الأطلس كثير منها، وبطاقتها تقف عند ما تسمّيه.',
        '[{"name":"Solamente","color":"#4A3728","force":"Full","wrapper":"غير معلن","vitolas":[],"story":"النجاح الأوّل — إصدار محدود بقياس واحد، 5 × 58."},{"name":"Dedicación","color":"#6B4226","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"الخطّ المنتظم الأوّل — تحيّة، كما يقول المؤسّس."},{"name":"Saint Francis","color":"#8B5A2B","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"فرنسيس الأسيزي — سنة 2021، أوّل قدّيس في الكتالوج."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Serino Cigar Co. ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Serino Cigar Co.',
        'nicaragua',
        '2016 — Carson et Tony Serino ; chez La Corona',
        'Sans usine — La Corona Cigars S.A. (Omar González-Alemán), Estelí',
        'cigaraficionado.com « Q&A: Carson Serino, Serino Cigar Co. » (père et fils lancent la maison en 2016 après avoir rencontré Omar González-Alemán, propriétaire de La Corona Cigars S.A. à Estelí ; Serino Royale, première ligne, assemblée ensemble ; Wayfarer en 2017 et Taíno, les lignes de Carson) ; cigardojo.com « Serino Cigar Co. Introduces First Cigar Releases » (mai 2016) ; serinocigars.com',
        'Serino est une affaire de père et de fils, Tony et Carson, lancée en 2016 après une rencontre : celle d''Omar González-Alemán, qui possède La Corona Cigars S.A., une fabrique d''Estelí. Ils y ont composé ensemble leur première ligne, Serino Royale, et c''est là que presque tout est roulé depuis. La Corona n''a pas de fiche dans cet atlas ; elle est nommée ici, et le sera tant qu''aucune marque propre ne justifiera la sienne.

Carson, le fils, a pris l''initiative des lignes suivantes : Wayfarer en 2017, puis Taíno — du nom du peuple des Caraïbes d''avant Colomb. Une maison qui commence par un assemblage à quatre mains et continue par ceux du fils : la transmission s''est faite en trois ans.

L''atlas la classe au Nicaragua, où se roule ce qu''elle vend, et garde le nom de la fabrique et de son propriétaire, parce que c''est la règle.',
        '[{"name":"Serino Royale","color":"#6B4226","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"La première ligne, 2016, composée à quatre mains chez La Corona."},{"name":"Wayfarer","color":"#5B3A29","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"La ligne de Carson, 2017."},{"name":"Taíno","color":"#8B5A2B","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Le peuple des Caraïbes d''avant Colomb."}]',
        'Serino is a father-and-son affair, Tony and Carson, launched in 2016 after a meeting: that of Omar González-Alemán, who owns La Corona Cigars S.A., a factory in Estelí. There they composed together their first line, Serino Royale, and that is where almost everything has been rolled since. La Corona has no entry in this atlas; it is named here, and will be as long as no brand of its own justifies one.

Carson, the son, took the lead on the following lines: Wayfarer in 2017, then Taíno — after the Caribbean people of before Columbus. A house that begins with a four-handed blend and continues with the son''s: the handover took three years.

This atlas classifies it in Nicaragua, where what it sells is rolled, and keeps the name of the factory and its owner, because that is the rule.',
        '[{"name":"Serino Royale","color":"#6B4226","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"The first line, 2016, composed four-handed at La Corona."},{"name":"Wayfarer","color":"#5B3A29","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"Carson''s line, 2017."},{"name":"Taíno","color":"#8B5A2B","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"The Caribbean people of before Columbus."}]',
        'Serino es un asunto de padre e hijo, Tony y Carson, lanzado en 2016 tras un encuentro: el de Omar González-Alemán, dueño de La Corona Cigars S.A., una fábrica de Estelí. Allí compusieron juntos su primera línea, Serino Royale, y allí se lía casi todo desde entonces. La Corona no tiene ficha en este atlas; se la nombra aquí, y así será mientras ninguna marca propia justifique la suya.

Carson, el hijo, tomó la iniciativa de las líneas siguientes: Wayfarer en 2017, luego Taíno — por el pueblo caribeño anterior a Colón. Una casa que empieza con una ligada a cuatro manos y sigue con las del hijo: el relevo se hizo en tres años.

Este atlas la clasifica en Nicaragua, donde se lía lo que vende, y conserva el nombre de la fábrica y de su dueño, porque esa es la regla.',
        '[{"name":"Serino Royale","color":"#6B4226","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"La primera línea, 2016, compuesta a cuatro manos en La Corona."},{"name":"Wayfarer","color":"#5B3A29","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"La línea de Carson, 2017."},{"name":"Taíno","color":"#8B5A2B","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"El pueblo caribeño anterior a Colón."}]',
        'Serino ist eine Sache von Vater und Sohn, Tony und Carson, lanciert 2016 nach einer Begegnung: der mit Omar González-Alemán, dem La Corona Cigars S.A. gehört, eine Fabrik in Estelí. Dort komponierten sie gemeinsam ihre erste Linie, Serino Royale, und dort wird seither fast alles gerollt. La Corona hat keinen Eintrag in diesem Atlas; sie wird hier genannt, und das bleibt so, solange keine eigene Marke einen rechtfertigt.

Carson, der Sohn, übernahm die Initiative für die folgenden Linien: Wayfarer 2017, dann Taíno — nach dem karibischen Volk vor Kolumbus. Ein Haus, das mit einem vierhändigen Blend beginnt und mit denen des Sohnes weitergeht: Die Übergabe dauerte drei Jahre.

Dieser Atlas ordnet es in Nicaragua ein, wo gerollt wird, was es verkauft, und behält den Namen der Fabrik und ihres Besitzers, weil das die Regel ist.',
        '[{"name":"Serino Royale","color":"#6B4226","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Die erste Linie, 2016, vierhändig bei La Corona komponiert."},{"name":"Wayfarer","color":"#5B3A29","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Carsons Linie, 2017."},{"name":"Taíno","color":"#8B5A2B","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Das karibische Volk vor Kolumbus."}]',
        'Serino 是一桩父子之事，托尼与卡森，2016年因一次相遇而创立：认识了埃斯特利 La Corona Cigars S.A. 工厂的老板奥马尔·冈萨雷斯-阿莱曼。他们在那里共同调配了第一条线 Serino Royale，此后几乎一切都在那里卷制。La Corona 在本图集中没有词条；此处点名，且只要没有自有品牌足以支撑，就一直只是点名。

儿子卡森主导了之后的系列：2017年的 Wayfarer，随后是 Taíno——以哥伦布之前的加勒比原住民命名。一家以四手调配起步、以儿子的调配延续的公司：传承在三年内完成。

本图集把它归入所售雪茄的卷制地尼加拉瓜，并保留工厂及其主人的名字——这是规则。',
        '[{"name":"Serino Royale","color":"#6B4226","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"第一条线，2016年，在 La Corona 四手调配。"},{"name":"Wayfarer","color":"#5B3A29","force":"Medium","wrapper":"未公开","vitolas":[],"story":"卡森的系列，2017年。"},{"name":"Taíno","color":"#8B5A2B","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"哥伦布之前的加勒比原住民。"}]',
        'سيرينو شأنُ أبٍ وابنه، توني وكارسون، أُطلق سنة 2016 بعد لقاء: لقاء عمر غونساليس-أليمان، صاحب La Corona Cigars S.A.، مصنعٍ في إستيلي. هناك ركّبا معًا خطّهما الأوّل، Serino Royale، وهناك يُلفّ كلّ شيء تقريبًا منذ ذلك الحين. ليس لِـLa Corona بطاقة في هذا الأطلس؛ تُسمّى هنا، وستبقى كذلك ما لم تُبرّر علامةٌ خاصة بطاقتها.

وتولّى كارسون، الابن، زمام الخطوط التالية: Wayfarer سنة 2017، ثم Taíno — على اسم شعب الكاريبي من قبل كولومبوس. دارٌ تبدأ بمزجة بأربع أيدٍ وتستمرّ بمزجات الابن: تمّ الانتقال في ثلاث سنوات.

يصنّفها هذا الأطلس في نيكاراغوا حيث يُلفّ ما تبيعه، ويحتفظ باسم المصنع وصاحبه، لأنّ هذه هي القاعدة.',
        '[{"name":"Serino Royale","color":"#6B4226","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"الخطّ الأوّل، 2016، رُكّب بأربع أيدٍ لدى La Corona."},{"name":"Wayfarer","color":"#5B3A29","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"خطّ كارسون، 2017."},{"name":"Taíno","color":"#8B5A2B","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"شعب الكاريبي من قبل كولومبوس."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Sindicato Cigar Group ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Sindicato Cigar Group',
        'nicaragua',
        '2013 — un groupe de détaillants ; chez Aganorsa',
        'Sans usine — Casa Fernández (Aganorsa Leaf), Estelí',
        'cigar-coop.com « Cigar Review: Sindicato » et cigardojo.com « Sindicato Corona Gorda » (fondée en 2013 par un groupe de détaillants devenus propriétaires de marque ; Jim Colucci, ancien vice-président d''Altadis USA, président ; Sindicato fait chez Casa Fernández sur les tabacs des fermes Fernández ; lancement avec Hex — cape Habano d''Équateur —, Affinity et Casa Bella — Connecticut d''Équateur, tripes du Nicaragua et de Rép. dominicaine) ; halfwheel.com « Particulares #1 » ; leafenthusiast.com « Brand Overview: Sindicato » ; sindicatocigars.com',
        'Sindicato est une marque de détaillants, et il faut dire tout de suite en quoi elle diffère de Black Swan, que cet atlas a refusée : ce n''est pas une série commandée par un vendeur à des fabriques tournantes, c''est une société — le Sindicato Cigar Group — fondée en 2013 par un groupe de propriétaires de boutiques qui ont voulu posséder leur marque, avec un catalogue permanent et un président qui vient du métier, Jim Colucci, ancien vice-président d''Altadis USA. Le nom dit le mode de propriété.

Tout est roulé chez Casa Fernández, à Estelí — Aganorsa Leaf aujourd''hui, dont l''atlas porte la fiche — sur les tabacs des fermes Fernández. Le lancement s''est fait avec trois assemblages : Hex, en cape Habano d''Équateur, et deux Connecticut d''Équateur, Affinity et Casa Bella, sur tripes nicaraguayenne et dominicaine. Le cigare qui porte le nom du groupe, Sindicato, est venu ensuite, puis Particulares, un nom d''ancienne marque cubaine repris.

Une marque conçue par ceux qui la vendent et roulée par une fabrique nommée : l''atlas la garde, et dit pourquoi.',
        '[{"name":"Hex","color":"#4A3728","force":"Full","wrapper":"Habano d''Équateur","vitolas":[],"story":"L''un des trois assemblages du lancement, 2013, sur tripes nicaraguayennes."},{"name":"Affinity","color":"#C9A96E","force":"Medium","wrapper":"Connecticut d''Équateur","vitolas":[],"story":"Le Connecticut du lancement, avec Casa Bella."},{"name":"Sindicato","color":"#6B4226","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Le cigare au nom du groupe, venu après les trois premiers."},{"name":"Particulares","color":"#7A2E1E","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"Un nom d''ancienne marque cubaine, repris."}]',
        'Sindicato is a retailers'' brand, and it must be said at once how it differs from Black Swan, which this atlas refused: it is not a series ordered by one seller from rotating factories, it is a company — the Sindicato Cigar Group — founded in 2013 by a group of shop owners who wanted to own their brand, with a permanent catalogue and a president from the trade, Jim Colucci, former vice-president of Altadis USA. The name states the mode of ownership.

Everything is rolled at Casa Fernández, in Estelí — Aganorsa Leaf today, whose entry this atlas carries — on tobacco from the Fernández farms. The launch came with three blends: Hex, in Ecuadorian Habano wrapper, and two Ecuadorian Connecticuts, Affinity and Casa Bella, over Nicaraguan and Dominican fillers. The cigar that bears the group''s name, Sindicato, came next, then Particulares, an old Cuban brand name taken up again.

A brand conceived by those who sell it and rolled by a named factory: this atlas keeps it, and says why.',
        '[{"name":"Hex","color":"#4A3728","force":"Full","wrapper":"Ecuadorian Habano","vitolas":[],"story":"One of the three launch blends, 2013, over Nicaraguan fillers."},{"name":"Affinity","color":"#C9A96E","force":"Medium","wrapper":"Ecuadorian Connecticut","vitolas":[],"story":"The launch Connecticut, with Casa Bella."},{"name":"Sindicato","color":"#6B4226","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"The cigar in the group''s name, which came after the first three."},{"name":"Particulares","color":"#7A2E1E","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"An old Cuban brand name, taken up again."}]',
        'Sindicato es una marca de minoristas, y hay que decir de inmediato en qué difiere de Black Swan, que este atlas rechazó: no es una serie encargada por un vendedor a fábricas rotativas, es una sociedad — el Sindicato Cigar Group — fundada en 2013 por un grupo de propietarios de tiendas que quisieron poseer su marca, con un catálogo permanente y un presidente venido del oficio, Jim Colucci, ex vicepresidente de Altadis USA. El nombre dice el modo de propiedad.

Todo se lía en Casa Fernández, en Estelí — Aganorsa Leaf hoy, cuya ficha lleva este atlas — con los tabacos de las fincas Fernández. El lanzamiento se hizo con tres ligadas: Hex, con capa Habano de Ecuador, y dos Connecticut de Ecuador, Affinity y Casa Bella, sobre tripas nicaragüense y dominicana. El puro que lleva el nombre del grupo, Sindicato, vino después, luego Particulares, un nombre de antigua marca cubana retomado.

Una marca concebida por quienes la venden y liada por una fábrica nombrada: este atlas la conserva, y dice por qué.',
        '[{"name":"Hex","color":"#4A3728","force":"Full","wrapper":"Habano de Ecuador","vitolas":[],"story":"Una de las tres ligadas del lanzamiento, 2013, sobre tripas nicaragüenses."},{"name":"Affinity","color":"#C9A96E","force":"Medium","wrapper":"Connecticut de Ecuador","vitolas":[],"story":"El Connecticut del lanzamiento, con Casa Bella."},{"name":"Sindicato","color":"#6B4226","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"El puro con el nombre del grupo, llegado tras los tres primeros."},{"name":"Particulares","color":"#7A2E1E","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"Un nombre de antigua marca cubana, retomado."}]',
        'Sindicato ist eine Händlermarke, und es muss sofort gesagt werden, worin sie sich von Black Swan unterscheidet, die dieser Atlas ablehnte: Sie ist keine von einem Verkäufer bei wechselnden Fabriken bestellte Serie, sondern eine Gesellschaft — die Sindicato Cigar Group —, 2013 gegründet von einer Gruppe von Ladeninhabern, die ihre Marke besitzen wollten, mit festem Katalog und einem Präsidenten aus dem Metier, Jim Colucci, ehemals Vizepräsident von Altadis USA. Der Name sagt die Eigentumsform.

Alles wird bei Casa Fernández in Estelí gerollt — heute Aganorsa Leaf, deren Eintrag dieser Atlas führt — auf Tabaken der Fernández-Farmen. Der Start erfolgte mit drei Blends: Hex, im ecuadorianischen Habano-Deckblatt, und zwei ecuadorianischen Connecticuts, Affinity und Casa Bella, über nicaraguanischer und dominikanischer Einlage. Die Zigarre mit dem Namen der Gruppe, Sindicato, kam danach, dann Particulares, ein wiederaufgenommener alter kubanischer Markenname.

Eine Marke, ersonnen von denen, die sie verkaufen, gerollt von einer benannten Fabrik: Dieser Atlas behält sie und sagt, warum.',
        '[{"name":"Hex","color":"#4A3728","force":"Full","wrapper":"Ecuadorianisches Habano","vitolas":[],"story":"Einer der drei Start-Blends, 2013, über nicaraguanischer Einlage."},{"name":"Affinity","color":"#C9A96E","force":"Medium","wrapper":"Ecuadorianisches Connecticut","vitolas":[],"story":"Das Start-Connecticut, mit Casa Bella."},{"name":"Sindicato","color":"#6B4226","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Die Zigarre mit dem Namen der Gruppe, nach den ersten drei gekommen."},{"name":"Particulares","color":"#7A2E1E","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Ein alter kubanischer Markenname, wiederaufgenommen."}]',
        'Sindicato 是零售商的品牌，须立即说明它与本图集拒收的 Black Swan 有何不同：它不是一个卖家向轮换工厂订制的系列，而是一家公司——Sindicato Cigar Group——2013年由一群想拥有自己品牌的店主创办，有常设目录，总裁出身行业：前 Altadis USA 副总裁吉姆·科卢奇。名字道出了所有权的形式。

一切都在埃斯特利的 Casa Fernández 卷制——即今日的 Aganorsa Leaf，本图集载有其词条——用费尔南德斯农场的烟叶。以三款配方起步：厄瓜多尔 Habano 茄衣的 Hex，以及两款厄瓜多尔康涅狄格茄衣、尼加拉瓜与多米尼加填充的 Affinity 与 Casa Bella。冠以集团之名的 Sindicato 随后推出，再是 Particulares——一个被重新启用的古巴老牌名。

由卖它的人构思、由点名的工厂卷制的牌子：本图集保留它，并说明理由。',
        '[{"name":"Hex","color":"#4A3728","force":"Full","wrapper":"厄瓜多尔 Habano","vitolas":[],"story":"2013年首发三款配方之一，尼加拉瓜填充。"},{"name":"Affinity","color":"#C9A96E","force":"Medium","wrapper":"厄瓜多尔康涅狄格","vitolas":[],"story":"首发的康涅狄格款，与 Casa Bella 同期。"},{"name":"Sindicato","color":"#6B4226","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"冠以集团之名的雪茄，在最初三款之后推出。"},{"name":"Particulares","color":"#7A2E1E","force":"Medium","wrapper":"未公开","vitolas":[],"story":"一个重新启用的古巴老牌名。"}]',
        'سينديكاتو علامةُ تجّار، ويجب أن يُقال فورًا فيمَ تختلف عن Black Swan التي رفضها هذا الأطلس: ليست سلسلةً يطلبها بائع واحد من مصانع متناوبة، بل شركة — Sindicato Cigar Group — أسّسها سنة 2013 مجموعةٌ من أصحاب المتاجر أرادوا امتلاك علامتهم، بكتالوج دائم ورئيس من أهل المهنة، جيم كولوتشي، نائب الرئيس السابق في Altadis USA. والاسم يقول نمط الملكية.

كلّ شيء يُلفّ لدى Casa Fernández في إستيلي — Aganorsa Leaf اليوم، التي يحمل هذا الأطلس بطاقتها — على أتبغة مزارع فرنانديس. جرى الإطلاق بثلاث مزجات: Hex بغلاف هابانو إكوادوري، وكونيتيكت إكوادوريان، Affinity وCasa Bella، على حشوتين نيكاراغوية ودومينيكية. وجاء السيجار الذي يحمل اسم المجموعة، Sindicato، بعد ذلك، ثم Particulares، اسمُ علامة كوبية قديمة أُعيد استعماله.

علامةٌ تصوّرها من يبيعونها ولفّها مصنعٌ مسمّى: يحتفظ بها هذا الأطلس، ويقول لماذا.',
        '[{"name":"Hex","color":"#4A3728","force":"Full","wrapper":"هابانو إكوادوري","vitolas":[],"story":"إحدى مزجات الإطلاق الثلاث، 2013، على حشوة نيكاراغوية."},{"name":"Affinity","color":"#C9A96E","force":"Medium","wrapper":"كونيتيكت إكوادوري","vitolas":[],"story":"كونيتيكت الإطلاق، مع Casa Bella."},{"name":"Sindicato","color":"#6B4226","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"السيجار الذي يحمل اسم المجموعة، جاء بعد الثلاثة الأوائل."},{"name":"Particulares","color":"#7A2E1E","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"اسمُ علامة كوبية قديمة أُعيد استعماله."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);


