UPDATE `producer_countries` SET `brands` = '[{"desc":"Référence absolue du Nicaragua premium","name":"Padrón","iconic":true},{"desc":"Pepin Garcia, maître torcedor légendaire","name":"My Father","iconic":true},{"desc":"Serie V mondialement reconnue","name":"Oliva","iconic":true},{"desc":"Liga Privada, révolution moderne","name":"Drew Estate","iconic":true},{"desc":"Plus grand producteur familial","name":"Plasencia","iconic":false},{"desc":"Élégance et puissance fusionnées","name":"Rocky Patel","iconic":false},{"desc":"Maître du Connecticut nicaraguayen","name":"Perdomo","iconic":false},{"desc":"Plus ancienne manufacture du pays","name":"Joya de Nicaragua","iconic":false},{"desc":"Le mélange privé de Jonathan Drew, devenu culte","name":"Liga Privada","iconic":false},{"desc":"Maison suisse de 1888, roulée à Estelí","name":"Villiger","iconic":false},{"desc":"Le rouleur que les autres marques employaient sans le nommer","name":"A.J. Fernandez","iconic":true},{"desc":"D''abord un planteur de Jalapa, ensuite une marque","name":"Aganorsa Leaf","iconic":true},{"desc":"La grammaire cubaine, la matière nicaraguayenne","name":"Tatuaje","iconic":false},{"desc":"Celle qui a rendu le petit format respectable","name":"Illusione","iconic":false},{"desc":"Un cigare ancré dans une culture, pas seulement un terroir","name":"Foundation Cigar Company","iconic":false},{"desc":"Granada plutôt qu''Estelí — et fermée depuis juin 2023","name":"Mombacho","iconic":false},{"desc":"Une marque qui s''est offert sa propre manufacture","name":"Espinosa","iconic":true},{"desc":"Pas d''usine : elle choisit son rouleur selon l''assemblage","name":"Crowned Heads","iconic":true},{"desc":"Des noms cubains d''avant 1960, des assemblages d''aujourd''hui","name":"Warped","iconic":false},{"desc":"Nodal compose, Plasencia fabrique, Tabacalera possède","name":"Capitol","iconic":false},{"desc":"Repris par la famille García en décembre 2019, après quarante-cinq ans chez Quesada","name":"Fonseca Nicaraguayen","iconic":false},{"name":"Nicoya","desc":"Maison australienne roulée à Estelí — l''Australie ne cultive plus depuis 2006","iconic":false},{"name":"Dunbarton Tobacco & Trust","desc":"Steve Saka, ex-Drew Estate, parti monter sa maison sans usine","iconic":true},{"name":"RoMa Craft Tobac","desc":"Commencée dans un garage, puis son propre atelier à Estelí","iconic":true},{"name":"Viaje","desc":"Plus de gamme régulière depuis 2012 : rien que des séries limitées","iconic":false},{"name":"Room101","desc":"D''un bijoutier au cigare ; trois manufactures, deux pays","iconic":false},{"name":"L''Atelier","desc":"La seconde maison de Pete Johnson, chez My Father comme Tatuaje","iconic":false},{"name":"La Aroma de Cuba","desc":"Nom cubain des années 1880, refait par Pepin García en 2009","iconic":false},{"name":"Southern Draw","desc":"Robert et Sharon Holt — un seul atelier, ce qui est rare","iconic":false},{"name":"HVC Cigars","desc":"Havana City ; dix ans sans usine, puis la sienne en 2021","iconic":true},{"name":"Fratello","desc":"Un ingénieur de la NASA passé au cigare","iconic":false},{"name":"Curivari","desc":"Grecque de tête, cubaine d''intention, nicaraguayenne de matière","iconic":false},{"name":"Black Label Trading Co.","desc":"Une fabrique conçue comme un atelier d''artiste","iconic":false},{"name":"Asylum","desc":"L''autre moitié de CLE — et une fabrique qui fut un cinéma","iconic":false},{"name":"Micallef","desc":"Une panne de voiture, un Texan, et trois générations cubaines","iconic":false},{"name":"Gurkha","desc":"Sans usine jusqu''en 2017, puis propriétaire de la sienne à Estelí","iconic":false},{"name":"Protocol","desc":"Deux policiers, aucune usine — La Zona puis San Lotano","iconic":false},{"name":"Regius","desc":"Maison londonienne de 2010, roulée chez Plasencia","iconic":false},{"name":"Cornelius & Anthony","desc":"Cent cinquante ans de tabac en Virginie, roulés à Estelí","iconic":false},{"name":"262 Cigars","desc":"Le nom est une date : février 1962, la signature de l''embargo","iconic":false},{"name":"Emilio Cigars","desc":"Trois fabriques, trois familles, un seul nom sur la bague","iconic":false},{"name":"Nomad","desc":"Le nom était un programme : elle a changé d''atelier et de pays","iconic":false},{"name":"7-20-4","desc":"Une adresse de Manchester fermée en 1962, reprise en 2006","iconic":false},{"name":"Cuban Crafters","desc":"Une boutique à Miami, mais la fabrique est à Estelí","iconic":false},{"name":"J. Fuego","desc":"Estelí, 2016 — le Corojo de Pinar del Río, et l''atelier où 7-20-4 est roulée","iconic":false},{"name":"Luciano Cigars","desc":"Estelí — la fabrique d''un Cubain parti en 2005, au prénom d''un financier brésilien ; roule Crowned Heads et Ozgener","iconic":false},{"name":"Agrotabacos","desc":"Condega, 1995 — les Ortez ; 60 % de la production pour des tiers, dont Altadis","iconic":false},{"name":"Karen Berger Cigars","desc":"Estelí — la fabrique de Kiki Berger, reprise par sa veuve en 2014 ; c''est aussi celle de Cuban Crafters","iconic":false},{"name":"Rojas Cigars","desc":"Estelí — un ancien cinéma ; l''assembleur d''Ezra Zion, Nomad et Stolen Throne","iconic":false},{"name":"Miami Cigar & Co.","desc":"1989 — Nestor et Mariana Miranda ; sans usine, la Collection chez My Father, Don Lino chez La Aurora","iconic":false},{"name":"1502 Cigars","desc":"L''année où Colomb touche le Nicaragua ; roulée chez Plasencia","iconic":false},{"name":"Crux Cigars","desc":"Deux détaillants du Minnesota passés de l''autre côté du comptoir en 2014 ; chez Plasencia","iconic":false},{"name":"Blanco Cigars","desc":"1998 — les cousins des Plasencia, de Pinar del Río ; roulée à Estelí","iconic":false},{"name":"Stolen Throne","desc":"Virginie, 2019 — roulée par Noel Rojas","iconic":false},{"name":"Ezra Zion","desc":"Texas, 2012 — roulée par Noel Rojas ; propriétaire de Nomad depuis 2018","iconic":false},{"name":"Ozgener Family Cigars","desc":"2022 — le fils du fondateur de CAO ; chez Luciano et La Alianza","iconic":false},{"name":"All Saints Cigars","desc":"2018 — chez Rocky Patel, à la TAVICUSA","iconic":false},{"name":"Serino Cigar Co.","desc":"2016 — père et fils ; chez La Corona","iconic":false},{"name":"Sindicato Cigar Group","desc":"2013 — des détaillants devenus propriétaires de marque ; chez Aganorsa","iconic":false}]' WHERE `id` = 'nicaragua';

INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` ELSE b.`gamme` END), 'machine', NOW()
  FROM `brands` b
  JOIN (SELECT 'history' champ UNION ALL SELECT 'gamme') c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE b.`name` IN ('Stolen Throne','Ezra Zion','Ozgener Family Cigars','All Saints Cigars','Serino Cigar Co.','Sindicato Cigar Group')
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `maj` = NOW();

DELETE FROM `moderation_log` WHERE `acteur_nom` = 'migration 212';
INSERT INTO `moderation_log`
  (`acteur_id`, `acteur_nom`, `portee`, `action`, `cible_type`, `cible_id`, `detail`)
VALUES
  (NULL,'migration 212','systeme','lot_4b_six_maisons_nicaraguayennes','marque',0,
   'Stolen Throne et Ezra Zion chez Rojas ; Ozgener chez Luciano ; All Saints chez Rocky Patel ; Serino chez La Corona ; Sindicato chez Aganorsa. Rangees par la fabrique qui les roule'),
  (NULL,'migration 212','systeme','ortega_reportee','marque',0,
   'La seule trace recente d Ortega Cigars est un catalogue de detaillant annoncant le retour du Cubao, sans date ni confirmation d activite. Une fiche au present sur une maison peut-etre dormante serait la faute de Mombacho a l envers'),
  (NULL,'migration 212','systeme','sindicato_n_est_pas_black_swan','marque',0,
   'Marque de detaillants gardee la ou Black Swan a ete refusee : une societe avec un catalogue permanent et une fabrique nommee, Casa Fernandez, pas une serie commandee a des fabriques tournantes. La fiche pose la distinction');

SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('Stolen Throne','Ezra Zion','Ozgener Family Cigars','All Saints Cigars','Serino Cigar Co.','Sindicato Cigar Group')) = 6 AS six_fiches,
  (SELECT `brands` LIKE '%Stolen Throne%' AND `brands` LIKE '%Sindicato%' FROM `producer_countries` WHERE `id` = 'nicaragua') AS nicaragua_annonce,
  (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 212') AS journal_non_tronque;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
